#!/usr/bin/env python3
"""Build and stage plugins generated by lunadash-create-plugin against the SDK."""
import argparse
import json
from pathlib import Path
import subprocess
import sys
import tempfile


def run(*command, ok=True):
    result = subprocess.run(command, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    if (result.returncode == 0) != ok:
        raise AssertionError(f'{" ".join(map(str, command))}\n{result.stdout}')
    return result


def build_and_install(project, build, sdk, prefix):
    run("cmake", "-S", str(project), "-B", str(build), "-G", "Ninja",
        f"-DLunaDashPlugin_DIR={sdk.resolve()}", f"-DCMAKE_INSTALL_PREFIX={prefix}")
    run("cmake", "--build", str(build), "--parallel", "2")
    run("cmake", "--install", str(build))
    manifest = json.loads((project / "metadata.json").read_text())
    installed = prefix / "share/lunadash/plugins" / manifest["id"]
    assert (installed / ".lunadash-sdk.json").is_file()
    return manifest, installed


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--sdk", type=Path, required=True)
    args = parser.parse_args()
    source = Path(__file__).resolve().parents[2]
    create = source / "scripts/create-plugin.py"

    listed = run(sys.executable, str(create), "--list").stdout
    assert "window-animation" in listed and "panel" not in listed, listed

    with tempfile.TemporaryDirectory(prefix="lunadash-sdk-test-") as directory:
        root = Path(directory)
        prefix = root / "install"
        projects = {}
        for name, target, language in (("cpp-rules", "window-rules", "cpp"),
                                       ("cpp-layout", "window-layout", "cpp"),
                                       ("cpp-animation", "window-animation", "cpp"),
                                       ("c-animation", "window-animation", "c")):
            project = root / name
            run(sys.executable, str(create), "--target", target, "--language", language,
                "--id", f"org.example.{name}", "--output", str(project))
            text = "\n".join(path.read_text() for path in project.iterdir())
            assert "Qt6" not in text and "#include <Q" not in text
            manifest, installed = build_and_install(
                project, root / (name + "-build"), args.sdk, prefix)
            assert (installed / manifest["entry"]).is_file()
            projects[name] = project
            print(f"Generated plugin built and staged: {name}")

        # Unsupported combinations are rejected before anything is written.
        run(sys.executable, str(create), "--target", "panel", "--id", "org.example.panel",
            "--output", str(root / "panel"), ok=False)
        run(sys.executable, str(create), "--target", "window-rules", "--language", "c",
            "--id", "org.example.c-rules", "--output", str(root / "c-rules"), ok=False)
        assert not (root / "panel").exists() and not (root / "c-rules").exists()

        multi = projects["cpp-animation"]
        multi_manifest = json.loads((multi / "metadata.json").read_text())
        animation = {
            "id": "window-animation",
            "type": multi_manifest.pop("type"),
            "target": multi_manifest.pop("target"),
            "mode": multi_manifest.pop("mode"),
            "entry": multi_manifest.pop("entry"),
            "settings": multi_manifest.pop("settings"),
        }
        rules = {
            "id": "window-rules",
            "type": "effect",
            "target": "window-rules",
            "mode": "replace",
            "entry": animation["entry"],
            "settings": {},
        }
        multi_manifest["targets"] = [animation, rules]
        (multi / "metadata.json").write_text(json.dumps(multi_manifest))
        _, installed = build_and_install(multi, root / "multi-target-build", args.sdk, prefix)
        assert (installed / animation["entry"]).is_file()
        print("SDK multi-target package built and staged")

        broken = projects["cpp-layout"] / "metadata.json"
        manifest = json.loads(broken.read_text())
        manifest["target"] = "panel"  # A shell slot cannot host a native effect.
        broken.write_text(json.dumps(manifest))
        run("cmake", "-S", str(broken.parent), "-B", str(root / "invalid"),
            f"-DLunaDashPlugin_DIR={args.sdk.resolve()}", ok=False)
        print("SDK rejects an incompatible target/type pair")

        text_control = projects["cpp-rules"] / "metadata.json"
        manifest = json.loads(text_control.read_text())
        manifest["settings"]["freeText"] = {
            "type": "string", "default": "custom", "control": "text"
        }
        text_control.write_text(json.dumps(manifest))
        run("cmake", "-S", str(text_control.parent),
            "-B", str(root / "invalid-text-control"),
            f"-DLunaDashPlugin_DIR={args.sdk.resolve()}", ok=False)
        print("SDK rejects plugin settings that require custom text controls")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
